window.START_COURSES.find(c=>c.id==="formacao-freudiana").modules.push({"id":"freud_m03","title":"Freud [1912–1917]","description":"Metapsicologia, narcisismo e debate institucional. Atenção: “A organização genital infantil” é de 1923, mas permanece neste módulo para respeitar o sumário original.","lessons":[{"id":"freud_a062","title":"Organização Genital Infantil #1","minutes":18,"hook":"Qual é o problema teórico por trás de “do modelo de 1905 à reelaboração de 1923” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “do modelo de 1905 à reelaboração de 1923”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1923, Freud retoma a sexualidade infantil e discute a chamada organização genital infantil. Essa obra não foi publicada entre 1912 e 1917, apesar de estar reunida assim no índice fornecido. Seu vocabulário sobre diferenças sexuais exige contextualização e leitura crítica: não é modelo normativo para identidades ou corpos."},{"title":"Entenda o conceito: Do modelo de 1905 à reelaboração de 1923","body":"Leia o ensaio como revisão, não como repetição simples dos Três ensaios. Freud tenta especificar modos pelos quais a sexualidade infantil é organizada.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O tema reaparece em A dissolução do complexo de Édipo e em Algumas consequências psíquicas da diferença anatômica entre os sexos. Não se deve ler um texto datado como consenso clínico atual.\n\nNota cronológica: publicação original em 1923, apesar da posição no módulo 1912–1917."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “do modelo de 1905 à reelaboração de 1923”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas crianças fazem perguntas diferentes sobre seus corpos. Uma escuta responsável não precisa encaixá-las num roteiro fixo de 'falta' ou 'completude' e deve respeitar o desenvolvimento e a proteção infantil.\n\nAgora retome o foco desta aula: do modelo de 1905 à reelaboração de 1923. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Organização genital infantil","desc":"Formulação freudiana de 1923 sobre sexualidade infantil, com pressupostos históricos debatidos."},{"term":"Falo","desc":"Termo cujo sentido em Freud não se confunde integralmente com seus desenvolvimentos posteriores em Lacan."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “do modelo de 1905 à reelaboração de 1923” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1923, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Do modelo de 1905 à reelaboração de 1923” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1923) — Organização Genital Infantil. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a063","title":"Organização Genital Infantil #2","minutes":15,"hook":"Qual é o problema teórico por trás de “o primado do falo e suas limitações” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “o primado do falo e suas limitações”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1923, Freud retoma a sexualidade infantil e discute a chamada organização genital infantil. Essa obra não foi publicada entre 1912 e 1917, apesar de estar reunida assim no índice fornecido. Seu vocabulário sobre diferenças sexuais exige contextualização e leitura crítica: não é modelo normativo para identidades ou corpos."},{"title":"Entenda o conceito: O primado do falo e suas limitações","body":"Freud descreve uma organização psíquica em termos historicamente centrados no falo. É fundamental distinguir a hipótese teórica de afirmações biológicas ou prescrições de gênero.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O tema reaparece em A dissolução do complexo de Édipo e em Algumas consequências psíquicas da diferença anatômica entre os sexos. Não se deve ler um texto datado como consenso clínico atual.\n\nNota cronológica: publicação original em 1923, apesar da posição no módulo 1912–1917."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “o primado do falo e suas limitações”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas crianças fazem perguntas diferentes sobre seus corpos. Uma escuta responsável não precisa encaixá-las num roteiro fixo de 'falta' ou 'completude' e deve respeitar o desenvolvimento e a proteção infantil.\n\nAgora retome o foco desta aula: o primado do falo e suas limitações. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Organização genital infantil","desc":"Formulação freudiana de 1923 sobre sexualidade infantil, com pressupostos históricos debatidos."},{"term":"Falo","desc":"Termo cujo sentido em Freud não se confunde integralmente com seus desenvolvimentos posteriores em Lacan."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “o primado do falo e suas limitações” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1923, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “O primado do falo e suas limitações” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1923) — Organização Genital Infantil. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a064","title":"Organização Genital Infantil #3","minutes":15,"hook":"Qual é o problema teórico por trás de “relações com édipo e castração” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “relações com édipo e castração”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1923, Freud retoma a sexualidade infantil e discute a chamada organização genital infantil. Essa obra não foi publicada entre 1912 e 1917, apesar de estar reunida assim no índice fornecido. Seu vocabulário sobre diferenças sexuais exige contextualização e leitura crítica: não é modelo normativo para identidades ou corpos."},{"title":"Entenda o conceito: Relações com Édipo e castração","body":"O texto articula fantasias, diferenças e conflitos infantis. Seu uso contemporâneo requer crítica explícita a interpretações que essencializam masculinidade, feminilidade ou identidade de gênero.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O tema reaparece em A dissolução do complexo de Édipo e em Algumas consequências psíquicas da diferença anatômica entre os sexos. Não se deve ler um texto datado como consenso clínico atual.\n\nNota cronológica: publicação original em 1923, apesar da posição no módulo 1912–1917."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “relações com édipo e castração”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas crianças fazem perguntas diferentes sobre seus corpos. Uma escuta responsável não precisa encaixá-las num roteiro fixo de 'falta' ou 'completude' e deve respeitar o desenvolvimento e a proteção infantil.\n\nAgora retome o foco desta aula: relações com édipo e castração. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Organização genital infantil","desc":"Formulação freudiana de 1923 sobre sexualidade infantil, com pressupostos históricos debatidos."},{"term":"Falo","desc":"Termo cujo sentido em Freud não se confunde integralmente com seus desenvolvimentos posteriores em Lacan."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “relações com édipo e castração” nesta obra?","options":["Examinar o argumento no contexto de 1923, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Relações com Édipo e castração” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1923) — Organização Genital Infantil. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a065","title":"Repressão","minutes":18,"hook":"Qual é o problema teórico por trás de “recalque e destino da representação” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “recalque e destino da representação”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O termo alemão Verdrängung é frequentemente traduzido como repressão ou recalque. Em 1915, Freud tenta sistematizar as condições e consequências desse processo defensivo. É importante diferenciá-lo da supressão voluntária de pensamentos e de outros mecanismos de defesa."},{"title":"Entenda o conceito: Recalque e destino da representação","body":"O recalque, no modelo freudiano, envolve operações que mantêm certas representações fora do acesso consciente enquanto seus efeitos continuam a aparecer em outras formações. A ideia de retorno do recalcado não significa que toda lembrança recuperada com emoção seja historicamente precisa.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare Repressão/Recalque com O inconsciente e com As neuropsicoses de defesa: os conceitos se refinam ao longo de duas décadas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “recalque e destino da representação”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa tenta não pensar em um episódio embaraçoso. Esse esforço consciente não basta para exemplificar recalque; é necessário entender a diferença conceitual entre 'não querer lembrar' e operação inconsciente.\n\nAgora retome o foco desta aula: recalque e destino da representação. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Recalque (Verdrängung)","desc":"Processo defensivo inconsciente central na teoria freudiana, distinto de esquecer voluntariamente."},{"term":"Retorno do recalcado","desc":"Conjunto de efeitos em que conflitos recalcados são pensados como retomando formas indiretas."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “recalque e destino da representação” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1915, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Recalque e destino da representação” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1915) — Repressão. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a066","title":"O Inconsciente #1","minutes":18,"hook":"Qual é o problema teórico por trás de “descritivo, dinâmico e sistemático” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “descritivo, dinâmico e sistemático”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"No ensaio metapsicológico de 1915, Freud distingue diversos sentidos do termo 'inconsciente' e propõe hipóteses sobre os sistemas psíquicos. Não basta dizer que inconsciente é aquilo de que não lembramos. A teoria envolve processos e relações específicos entre representação, afetos e consciência."},{"title":"Entenda o conceito: Descritivo, dinâmico e sistemático","body":"Freud diferencia usos do termo e evita reduzir o inconsciente a um depósito de lembranças. O sentido dinâmico destaca forças em conflito e barreiras ao tornar-se consciente.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A segunda tópica de 1923 mostrará que nem todo elemento inconsciente se localiza simplesmente num mesmo sistema; isso reconfigura a visão didática de 'caixinhas'."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “descritivo, dinâmico e sistemático”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Alguém relata que entende racionalmente sua ansiedade, mas continua repetindo certos comportamentos. O relato pode abrir uma investigação sobre conflito inconsciente, sem permitir definir de antemão qual conflito é esse.\n\nAgora retome o foco desta aula: descritivo, dinâmico e sistemático. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Inconsciente descritivo","desc":"Aquilo que não está consciente num momento determinado."},{"term":"Inconsciente dinâmico","desc":"Processos inconscientes pensados em relação a conflito e defesa."},{"term":"Metapsicologia","desc":"Modelo conceitual freudiano dos processos psíquicos sob pontos de vista específicos."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “descritivo, dinâmico e sistemático” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1915, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Descritivo, dinâmico e sistemático” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1915) — O Inconsciente. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a067","title":"O Inconsciente #2","minutes":15,"hook":"Qual é o problema teórico por trás de “características dos processos inconscientes” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “características dos processos inconscientes”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"No ensaio metapsicológico de 1915, Freud distingue diversos sentidos do termo 'inconsciente' e propõe hipóteses sobre os sistemas psíquicos. Não basta dizer que inconsciente é aquilo de que não lembramos. A teoria envolve processos e relações específicos entre representação, afetos e consciência."},{"title":"Entenda o conceito: Características dos processos inconscientes","body":"O autor discute ausência de certas relações temporais e contradições, mobilidade de investimentos e outros traços de seu modelo. São proposições metapsicológicas a estudar, não fotografias do cérebro.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A segunda tópica de 1923 mostrará que nem todo elemento inconsciente se localiza simplesmente num mesmo sistema; isso reconfigura a visão didática de 'caixinhas'."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “características dos processos inconscientes”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Alguém relata que entende racionalmente sua ansiedade, mas continua repetindo certos comportamentos. O relato pode abrir uma investigação sobre conflito inconsciente, sem permitir definir de antemão qual conflito é esse.\n\nAgora retome o foco desta aula: características dos processos inconscientes. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Inconsciente descritivo","desc":"Aquilo que não está consciente num momento determinado."},{"term":"Inconsciente dinâmico","desc":"Processos inconscientes pensados em relação a conflito e defesa."},{"term":"Metapsicologia","desc":"Modelo conceitual freudiano dos processos psíquicos sob pontos de vista específicos."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “características dos processos inconscientes” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1915, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Características dos processos inconscientes” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1915) — O Inconsciente. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a068","title":"O Inconsciente #3","minutes":15,"hook":"Qual é o problema teórico por trás de “representação de coisa, representação de palavra” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “representação de coisa, representação de palavra”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"No ensaio metapsicológico de 1915, Freud distingue diversos sentidos do termo 'inconsciente' e propõe hipóteses sobre os sistemas psíquicos. Não basta dizer que inconsciente é aquilo de que não lembramos. A teoria envolve processos e relações específicos entre representação, afetos e consciência."},{"title":"Entenda o conceito: Representação de coisa, representação de palavra","body":"A ligação entre representações e linguagem ganha importância para pensar acesso à consciência e funcionamento psíquico. Não se deve confundir essa distinção com conceitos lacanianos posteriores sem explicitar as diferenças.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A segunda tópica de 1923 mostrará que nem todo elemento inconsciente se localiza simplesmente num mesmo sistema; isso reconfigura a visão didática de 'caixinhas'."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “representação de coisa, representação de palavra”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Alguém relata que entende racionalmente sua ansiedade, mas continua repetindo certos comportamentos. O relato pode abrir uma investigação sobre conflito inconsciente, sem permitir definir de antemão qual conflito é esse.\n\nAgora retome o foco desta aula: representação de coisa, representação de palavra. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Inconsciente descritivo","desc":"Aquilo que não está consciente num momento determinado."},{"term":"Inconsciente dinâmico","desc":"Processos inconscientes pensados em relação a conflito e defesa."},{"term":"Metapsicologia","desc":"Modelo conceitual freudiano dos processos psíquicos sob pontos de vista específicos."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “representação de coisa, representação de palavra” nesta obra?","options":["Examinar o argumento no contexto de 1915, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Representação de coisa, representação de palavra” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1915) — O Inconsciente. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a069","title":"Totem e Tabu","minutes":18,"hook":"Qual é o problema teórico por trás de “a hipótese do pai primevo e o mito teórico” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “a hipótese do pai primevo e o mito teórico”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud reúne ensaios que aproximam psicanálise, antropologia e hipóteses sobre origem da cultura, interdições e parentesco. Várias premissas etnológicas são hoje contestadas ou ultrapassadas; o texto deve ser lido como construção especulativa e documento histórico, não como descrição factual da origem das sociedades humanas."},{"title":"Entenda o conceito: A hipótese do pai primevo e o mito teórico","body":"Freud mobiliza narrativas sobre proibição, culpa e organização social para explorar relações entre desejo e lei. O aluno precisa separar argumento simbólico, mito explicativo e evidência histórica. A antropologia contemporânea não endossa essa reconstrução como fato universal.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto dialoga com a reflexão freudiana sobre religião e cultura, depois elaborada em O futuro de uma ilusão e O mal-estar na civilização.\n\nAdvertência: evitar reproduzir como fatos premissas etnológicas e coloniais hoje problematizadas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “a hipótese do pai primevo e o mito teórico”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Ao estudar uma comunidade real, não se deve deduzir sua cultura a partir do 'pai da horda' freudiano. A hipótese pode ser examinada como elaboração da teoria, não como descrição etnográfica.\n\nAgora retome o foco desta aula: a hipótese do pai primevo e o mito teórico. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Tabu","desc":"Interdição cultural que Freud investiga em abordagem histórica especulativa."},{"term":"Pai primevo","desc":"Figura hipotética do mito teórico utilizado por Freud, não personagem histórico comprovado."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “a hipótese do pai primevo e o mito teórico” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1913, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “A hipótese do pai primevo e o mito teórico” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1913) — Totem e Tabu. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a070","title":"A História do Movimento Psicanalítico #1","minutes":18,"hook":"Qual é o problema teórico por trás de “do trabalho inicial à organização do movimento” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “do trabalho inicial à organização do movimento”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1914, Freud apresenta uma narrativa da formação do movimento psicanalítico e de suas divergências com colegas. É fonte primária de enorme valor, mas escrita por um participante diretamente envolvido nos conflitos. Para compreendê-la, compare seu ponto de vista com histórias do movimento e com documentos de outros autores."},{"title":"Entenda o conceito: Do trabalho inicial à organização do movimento","body":"Freud reconstitui sua própria trajetória e a constituição de um campo compartilhado. Observe como ele define fronteiras entre psicanálise e abordagens concorrentes.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A construção de uma disciplina inclui disputas sobre conceitos, prática e legitimidade. O estudo crítico não exige desqualificar integralmente seus protagonistas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “do trabalho inicial à organização do movimento”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas escolas descrevem de maneira oposta a mesma divergência. Uma leitura histórica compara fontes, datas e formulações, em vez de escolher automaticamente a narrativa de quem fundou a instituição.\n\nAgora retome o foco desta aula: do trabalho inicial à organização do movimento. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Movimento psicanalítico","desc":"Redes de estudo, prática e instituições que se organizaram em torno da psicanálise."},{"term":"Fonte primária","desc":"Documento produzido diretamente por um protagonista do período investigado."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “do trabalho inicial à organização do movimento” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1914, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Do trabalho inicial à organização do movimento” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1914) — A História do Movimento Psicanalítico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a071","title":"A História do Movimento Psicanalítico #2","minutes":15,"hook":"Qual é o problema teórico por trás de “grupos, instituições e circulação internacional” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “grupos, instituições e circulação internacional”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1914, Freud apresenta uma narrativa da formação do movimento psicanalítico e de suas divergências com colegas. É fonte primária de enorme valor, mas escrita por um participante diretamente envolvido nos conflitos. Para compreendê-la, compare seu ponto de vista com histórias do movimento e com documentos de outros autores."},{"title":"Entenda o conceito: Grupos, instituições e circulação internacional","body":"O movimento envolve encontros, correspondências, publicações e formação. A organização institucional participa da definição do que passa a contar como teoria e técnica legítimas.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A construção de uma disciplina inclui disputas sobre conceitos, prática e legitimidade. O estudo crítico não exige desqualificar integralmente seus protagonistas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “grupos, instituições e circulação internacional”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas escolas descrevem de maneira oposta a mesma divergência. Uma leitura histórica compara fontes, datas e formulações, em vez de escolher automaticamente a narrativa de quem fundou a instituição.\n\nAgora retome o foco desta aula: grupos, instituições e circulação internacional. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Movimento psicanalítico","desc":"Redes de estudo, prática e instituições que se organizaram em torno da psicanálise."},{"term":"Fonte primária","desc":"Documento produzido diretamente por um protagonista do período investigado."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “grupos, instituições e circulação internacional” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1914, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Grupos, instituições e circulação internacional” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1914) — A História do Movimento Psicanalítico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a072","title":"A História do Movimento Psicanalítico #3","minutes":15,"hook":"Qual é o problema teórico por trás de “divergências com adler e jung” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “divergências com adler e jung”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1914, Freud apresenta uma narrativa da formação do movimento psicanalítico e de suas divergências com colegas. É fonte primária de enorme valor, mas escrita por um participante diretamente envolvido nos conflitos. Para compreendê-la, compare seu ponto de vista com histórias do movimento e com documentos de outros autores."},{"title":"Entenda o conceito: Divergências com Adler e Jung","body":"Freud interpreta rupturas em torno da libido, sexualidade e conflito. Há também dimensões pessoais e institucionais, que não se resolvem apenas pela adesão ao relato de um lado.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A construção de uma disciplina inclui disputas sobre conceitos, prática e legitimidade. O estudo crítico não exige desqualificar integralmente seus protagonistas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “divergências com adler e jung”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas escolas descrevem de maneira oposta a mesma divergência. Uma leitura histórica compara fontes, datas e formulações, em vez de escolher automaticamente a narrativa de quem fundou a instituição.\n\nAgora retome o foco desta aula: divergências com adler e jung. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Movimento psicanalítico","desc":"Redes de estudo, prática e instituições que se organizaram em torno da psicanálise."},{"term":"Fonte primária","desc":"Documento produzido diretamente por um protagonista do período investigado."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “divergências com adler e jung” nesta obra?","options":["Examinar o argumento no contexto de 1914, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Divergências com Adler e Jung” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1914) — A História do Movimento Psicanalítico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a073","title":"A História do Movimento Psicanalítico #4","minutes":15,"hook":"Qual é o problema teórico por trás de “como ler uma história escrita por um protagonista” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “como ler uma história escrita por um protagonista”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1914, Freud apresenta uma narrativa da formação do movimento psicanalítico e de suas divergências com colegas. É fonte primária de enorme valor, mas escrita por um participante diretamente envolvido nos conflitos. Para compreendê-la, compare seu ponto de vista com histórias do movimento e com documentos de outros autores."},{"title":"Entenda o conceito: Como ler uma história escrita por um protagonista","body":"Treine identificar argumento, polêmica e evidência. Um relato autobiográfico de conflito não substitui pesquisa historiográfica, embora seja essencial para conhecer a posição de Freud.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A construção de uma disciplina inclui disputas sobre conceitos, prática e legitimidade. O estudo crítico não exige desqualificar integralmente seus protagonistas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “como ler uma história escrita por um protagonista”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Duas escolas descrevem de maneira oposta a mesma divergência. Uma leitura histórica compara fontes, datas e formulações, em vez de escolher automaticamente a narrativa de quem fundou a instituição.\n\nAgora retome o foco desta aula: como ler uma história escrita por um protagonista. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Movimento psicanalítico","desc":"Redes de estudo, prática e instituições que se organizaram em torno da psicanálise."},{"term":"Fonte primária","desc":"Documento produzido diretamente por um protagonista do período investigado."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “como ler uma história escrita por um protagonista” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1914, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Como ler uma história escrita por um protagonista” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1914) — A História do Movimento Psicanalítico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a074","title":"Sobre o Narcisismo: uma Introdução #1","minutes":18,"hook":"Qual é o problema teórico por trás de “narcisismo primário e investimentos” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “narcisismo primário e investimentos”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O texto de 1914 amplia a teoria da libido e introduz distinções entre investimento narcísico e de objeto. Freud examina autoimagem, ideais e relações com outros. Narcisismo aqui não equivale a rótulo moral de pessoa vaidosa nem a diagnóstico psiquiátrico contemporâneo."},{"title":"Entenda o conceito: Narcisismo primário e investimentos","body":"Freud propõe um modelo de circulação de investimentos libidinais entre eu e objetos. Trata-se de construção teórica, não de quantidade mensurável de amor próprio.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Este texto conecta sexualidade, perda, identificação e formação do eu. Sua leitura ajuda a compreender Luto e melancolia e O eu e o id."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “narcisismo primário e investimentos”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sente vergonha por não corresponder a um ideal de sucesso. Isso permite discutir ideais e autoavaliação, mas não faz dela necessariamente 'narcisista' em sentido clínico.\n\nAgora retome o foco desta aula: narcisismo primário e investimentos. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Narcisismo","desc":"Conceito freudiano sobre investimento libidinal no eu."},{"term":"Ideal do eu","desc":"Formulação vinculada a ideais e autoavaliação, reelaborada por autores posteriores."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “narcisismo primário e investimentos” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1914, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Narcisismo primário e investimentos” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1914) — Sobre o Narcisismo: uma Introdução. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a075","title":"Sobre o Narcisismo: uma Introdução #2","minutes":15,"hook":"Qual é o problema teórico por trás de “eu ideal, ideal do eu e formas de reconhecimento” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “eu ideal, ideal do eu e formas de reconhecimento”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O texto de 1914 amplia a teoria da libido e introduz distinções entre investimento narcísico e de objeto. Freud examina autoimagem, ideais e relações com outros. Narcisismo aqui não equivale a rótulo moral de pessoa vaidosa nem a diagnóstico psiquiátrico contemporâneo."},{"title":"Entenda o conceito: Eu ideal, ideal do eu e formas de reconhecimento","body":"As formulações sobre ideais e autoavaliação ajudam a estudar exigências internas e a relação com o olhar alheio. Posteriores autores modificam os termos; não projete automaticamente distinções lacanianas sobre cada frase freudiana.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Este texto conecta sexualidade, perda, identificação e formação do eu. Sua leitura ajuda a compreender Luto e melancolia e O eu e o id."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “eu ideal, ideal do eu e formas de reconhecimento”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sente vergonha por não corresponder a um ideal de sucesso. Isso permite discutir ideais e autoavaliação, mas não faz dela necessariamente 'narcisista' em sentido clínico.\n\nAgora retome o foco desta aula: eu ideal, ideal do eu e formas de reconhecimento. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Narcisismo","desc":"Conceito freudiano sobre investimento libidinal no eu."},{"term":"Ideal do eu","desc":"Formulação vinculada a ideais e autoavaliação, reelaborada por autores posteriores."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “eu ideal, ideal do eu e formas de reconhecimento” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1914, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Eu ideal, ideal do eu e formas de reconhecimento” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1914) — Sobre o Narcisismo: uma Introdução. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a076","title":"Instinto e Suas Vicissitudes #1","minutes":18,"hook":"Qual é o problema teórico por trás de “o que freud chama trieb?” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “o que freud chama trieb?”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O texto é frequentemente traduzido como Os instintos e seus destinos ou Pulsões e destinos da pulsão (Triebe und Triebschicksale). A tradução de Trieb por 'instinto' ou 'pulsão' envolve escolhas conceituais relevantes. Freud apresenta fonte, pressão, meta e objeto da pulsão e discute seus destinos."},{"title":"Entenda o conceito: O que Freud chama Trieb?","body":"Pulsão não é simplesmente reflexo biológico com objeto fixo. A formulação situa um conceito-limite entre somático e psíquico e introduz dificuldades centrais de tradução.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto é uma das peças da metapsicologia de 1915 e deve ser articulado ao conceito de recalque e às mudanças pulsionais de 1920.\n\nNota de tradução: “instinto” nas imagens corresponde a Trieb; algumas traduções preferem “pulsão”."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “o que freud chama trieb?”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa transforma uma intensa inquietação em atividade criativa. Isso pode ilustrar uma pergunta sobre sublimação, mas não estabelece sozinho que houve um destino pulsional identificável.\n\nAgora retome o foco desta aula: o que freud chama trieb?. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Trieb","desc":"Termo alemão usualmente traduzido por pulsão ou instinto; há controvérsias tradutórias."},{"term":"Sublimação","desc":"Destino pulsional proposto por Freud em relação a mudanças de meta e modalidades de satisfação."},{"term":"Objeto pulsional","desc":"Elemento relativo ao qual a pulsão pode buscar satisfação, não necessariamente fixo."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “o que freud chama trieb?” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1915, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “O que Freud chama Trieb?” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1915) — Triebe und Triebschicksale; traduções: Os instintos e seus destinos / Pulsões e seus destinos.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a077","title":"Instinto e Suas Vicissitudes #2","minutes":15,"hook":"Qual é o problema teórico por trás de “pressão, fonte, meta e objeto” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “pressão, fonte, meta e objeto”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O texto é frequentemente traduzido como Os instintos e seus destinos ou Pulsões e destinos da pulsão (Triebe und Triebschicksale). A tradução de Trieb por 'instinto' ou 'pulsão' envolve escolhas conceituais relevantes. Freud apresenta fonte, pressão, meta e objeto da pulsão e discute seus destinos."},{"title":"Entenda o conceito: Pressão, fonte, meta e objeto","body":"A pulsão é caracterizada por componentes teóricos. O objeto é variável em relação à satisfação, o que dificulta reduzir a sexualidade a um comportamento predeterminado.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto é uma das peças da metapsicologia de 1915 e deve ser articulado ao conceito de recalque e às mudanças pulsionais de 1920.\n\nNota de tradução: “instinto” nas imagens corresponde a Trieb; algumas traduções preferem “pulsão”."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “pressão, fonte, meta e objeto”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa transforma uma intensa inquietação em atividade criativa. Isso pode ilustrar uma pergunta sobre sublimação, mas não estabelece sozinho que houve um destino pulsional identificável.\n\nAgora retome o foco desta aula: pressão, fonte, meta e objeto. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Trieb","desc":"Termo alemão usualmente traduzido por pulsão ou instinto; há controvérsias tradutórias."},{"term":"Sublimação","desc":"Destino pulsional proposto por Freud em relação a mudanças de meta e modalidades de satisfação."},{"term":"Objeto pulsional","desc":"Elemento relativo ao qual a pulsão pode buscar satisfação, não necessariamente fixo."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “pressão, fonte, meta e objeto” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1915, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Pressão, fonte, meta e objeto” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1915) — Triebe und Triebschicksale; traduções: Os instintos e seus destinos / Pulsões e seus destinos.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a078","title":"Instinto e Suas Vicissitudes #3","minutes":15,"hook":"Qual é o problema teórico por trás de “transformação no contrário e retorno contra a própria pessoa” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “transformação no contrário e retorno contra a própria pessoa”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O texto é frequentemente traduzido como Os instintos e seus destinos ou Pulsões e destinos da pulsão (Triebe und Triebschicksale). A tradução de Trieb por 'instinto' ou 'pulsão' envolve escolhas conceituais relevantes. Freud apresenta fonte, pressão, meta e objeto da pulsão e discute seus destinos."},{"title":"Entenda o conceito: Transformação no contrário e retorno contra a própria pessoa","body":"Freud descreve destinos possíveis de pulsões e muda a pergunta de 'quanto desejo existe?' para 'como ele se organiza e se transforma?'.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto é uma das peças da metapsicologia de 1915 e deve ser articulado ao conceito de recalque e às mudanças pulsionais de 1920.\n\nNota de tradução: “instinto” nas imagens corresponde a Trieb; algumas traduções preferem “pulsão”."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “transformação no contrário e retorno contra a própria pessoa”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa transforma uma intensa inquietação em atividade criativa. Isso pode ilustrar uma pergunta sobre sublimação, mas não estabelece sozinho que houve um destino pulsional identificável.\n\nAgora retome o foco desta aula: transformação no contrário e retorno contra a própria pessoa. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Trieb","desc":"Termo alemão usualmente traduzido por pulsão ou instinto; há controvérsias tradutórias."},{"term":"Sublimação","desc":"Destino pulsional proposto por Freud em relação a mudanças de meta e modalidades de satisfação."},{"term":"Objeto pulsional","desc":"Elemento relativo ao qual a pulsão pode buscar satisfação, não necessariamente fixo."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “transformação no contrário e retorno contra a própria pessoa” nesta obra?","options":["Examinar o argumento no contexto de 1915, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Transformação no contrário e retorno contra a própria pessoa” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1915) — Triebe und Triebschicksale; traduções: Os instintos e seus destinos / Pulsões e seus destinos.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a079","title":"Instinto e Suas Vicissitudes #4","minutes":15,"hook":"Qual é o problema teórico por trás de “recalque e sublimação” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “recalque e sublimação”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"O texto é frequentemente traduzido como Os instintos e seus destinos ou Pulsões e destinos da pulsão (Triebe und Triebschicksale). A tradução de Trieb por 'instinto' ou 'pulsão' envolve escolhas conceituais relevantes. Freud apresenta fonte, pressão, meta e objeto da pulsão e discute seus destinos."},{"title":"Entenda o conceito: Recalque e sublimação","body":"O texto permite distinguir operações defensivas de percursos de satisfação socialmente transformados. Sublimação não é sinônimo de 'energia ruim transformada em arte' em qualquer situação.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto é uma das peças da metapsicologia de 1915 e deve ser articulado ao conceito de recalque e às mudanças pulsionais de 1920.\n\nNota de tradução: “instinto” nas imagens corresponde a Trieb; algumas traduções preferem “pulsão”."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “recalque e sublimação”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa transforma uma intensa inquietação em atividade criativa. Isso pode ilustrar uma pergunta sobre sublimação, mas não estabelece sozinho que houve um destino pulsional identificável.\n\nAgora retome o foco desta aula: recalque e sublimação. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Trieb","desc":"Termo alemão usualmente traduzido por pulsão ou instinto; há controvérsias tradutórias."},{"term":"Sublimação","desc":"Destino pulsional proposto por Freud em relação a mudanças de meta e modalidades de satisfação."},{"term":"Objeto pulsional","desc":"Elemento relativo ao qual a pulsão pode buscar satisfação, não necessariamente fixo."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “recalque e sublimação” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1915, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Recalque e sublimação” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1915) — Triebe und Triebschicksale; traduções: Os instintos e seus destinos / Pulsões e seus destinos.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a080","title":"Alguns Tipos de Caráter Encontrados na Prática Psicanalítica (aula 1) #1","minutes":18,"hook":"Qual é o problema teórico por trás de “as exceções: sofrimento e pretensão de compensação” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “as exceções: sofrimento e pretensão de compensação”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud apresenta figuras narrativas e situações clínicas para discutir conflitos entre desejo, culpa e formas de caráter. Os títulos 'tipo' e 'caráter' têm sentidos históricos; não constituem tipologias para etiquetar pessoas no atendimento atual."},{"title":"Entenda o conceito: As exceções: sofrimento e pretensão de compensação","body":"Freud explora posições subjetivas relacionadas à ideia de ter sofrido demais para aceitar novas frustrações. A leitura não deve desqualificar reivindicações legítimas de reparação por injustiças reais.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare esses ensaios com narcisismo, culpa e ideal do eu. O contexto social pode ser tão relevante quanto a hipótese intrapsíquica."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “as exceções: sofrimento e pretensão de compensação”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa perde uma promoção após discriminação documentada. Atribuir o fato diretamente a um 'fracasso no êxito' seria desconsiderar a realidade e produzir violência interpretativa.\n\nAgora retome o foco desta aula: as exceções: sofrimento e pretensão de compensação. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Caráter","desc":"Modo de organização psíquica abordado nas tipologias históricas de Freud."},{"term":"Culpa inconsciente","desc":"Hipótese sobre efeitos de conflitos sem consciência clara de culpabilidade."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “as exceções: sofrimento e pretensão de compensação” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1916, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “As exceções: sofrimento e pretensão de compensação” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1916) — Alguns Tipos de Caráter Encontrados na Prática Psicanalítica. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a081","title":"Alguns Tipos de Caráter Encontrados na Prática Psicanalítica (aula 1) #2","minutes":15,"hook":"Qual é o problema teórico por trás de “os que fracassam quando triunfam” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “os que fracassam quando triunfam”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud apresenta figuras narrativas e situações clínicas para discutir conflitos entre desejo, culpa e formas de caráter. Os títulos 'tipo' e 'caráter' têm sentidos históricos; não constituem tipologias para etiquetar pessoas no atendimento atual."},{"title":"Entenda o conceito: Os que fracassam quando triunfam","body":"A hipótese de culpa ou conflito diante do êxito levanta questões sobre ideais e proibição interna. Não se pode deduzir inconscientemente 'medo do sucesso' quando alguém enfrenta barreiras objetivas.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare esses ensaios com narcisismo, culpa e ideal do eu. O contexto social pode ser tão relevante quanto a hipótese intrapsíquica."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “os que fracassam quando triunfam”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa perde uma promoção após discriminação documentada. Atribuir o fato diretamente a um 'fracasso no êxito' seria desconsiderar a realidade e produzir violência interpretativa.\n\nAgora retome o foco desta aula: os que fracassam quando triunfam. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Caráter","desc":"Modo de organização psíquica abordado nas tipologias históricas de Freud."},{"term":"Culpa inconsciente","desc":"Hipótese sobre efeitos de conflitos sem consciência clara de culpabilidade."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “os que fracassam quando triunfam” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1916, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Os que fracassam quando triunfam” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1916) — Alguns Tipos de Caráter Encontrados na Prática Psicanalítica. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a082","title":"Alguns Tipos de Caráter Encontrados no Trabalho Psicanalítico (aula 2) #3","minutes":18,"hook":"Qual é o problema teórico por trás de “criminosos por sentimento de culpa” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “criminosos por sentimento de culpa”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Na continuação do estudo de caráter, o interesse recai em ações transgressoras e culpa. Freud investiga como certas narrativas invertem a intuição de que culpa surgiria apenas depois de um ato. O texto propõe hipóteses e não autoriza responsabilizar vítimas nem absolver autores de danos."},{"title":"Entenda o conceito: Criminosos por sentimento de culpa","body":"Freud sugere, em certas circunstâncias, que sentimentos prévios de culpa podem estar ligados a transgressões. Não é explicação geral da criminalidade e não substitui direito, sociologia ou avaliação forense.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A análise de caráter é histórica e limitada; não se deve confundi-la com psicologia jurídica contemporânea ou diagnóstico de personalidade."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “criminosos por sentimento de culpa”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa relata ter agido de forma contrária a seus valores. É legítimo investigar sua experiência afetiva sem inferir que toda conduta contrária à lei resulta de culpa inconsciente.\n\nAgora retome o foco desta aula: criminosos por sentimento de culpa. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Sentimento de culpa","desc":"Experiência ou hipótese psíquica de autoacusação, com modalidades conscientes e inconscientes."},{"term":"Responsabilidade","desc":"Dimensão ética e jurídica que não se dissolve em explicações psicanalíticas."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “criminosos por sentimento de culpa” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1916, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Criminosos por sentimento de culpa” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1916) — Alguns Tipos de Caráter Encontrados no Trabalho Psicanalítico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a083","title":"Alguns Tipos de Caráter Encontrados no Trabalho Psicanalítico (aula 2) #4","minutes":15,"hook":"Qual é o problema teórico por trás de “crítica das aplicações automáticas” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “crítica das aplicações automáticas”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Na continuação do estudo de caráter, o interesse recai em ações transgressoras e culpa. Freud investiga como certas narrativas invertem a intuição de que culpa surgiria apenas depois de um ato. O texto propõe hipóteses e não autoriza responsabilizar vítimas nem absolver autores de danos."},{"title":"Entenda o conceito: Crítica das aplicações automáticas","body":"A hipótese intrapsíquica nunca torna um ato inevitável nem elimina responsabilidade. Ler clinicamente é distinguir motivação possível, narrativa individual e prova jurídica.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"A análise de caráter é histórica e limitada; não se deve confundi-la com psicologia jurídica contemporânea ou diagnóstico de personalidade."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “crítica das aplicações automáticas”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa relata ter agido de forma contrária a seus valores. É legítimo investigar sua experiência afetiva sem inferir que toda conduta contrária à lei resulta de culpa inconsciente.\n\nAgora retome o foco desta aula: crítica das aplicações automáticas. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Sentimento de culpa","desc":"Experiência ou hipótese psíquica de autoacusação, com modalidades conscientes e inconscientes."},{"term":"Responsabilidade","desc":"Dimensão ética e jurídica que não se dissolve em explicações psicanalíticas."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “crítica das aplicações automáticas” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1916, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Crítica das aplicações automáticas” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1916) — Alguns Tipos de Caráter Encontrados no Trabalho Psicanalítico. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a084","title":"Conferências Introdutórias Sobre Psicanálise #1","minutes":18,"hook":"Qual é o problema teórico por trás de “atos falhos: por que começar pelo pequeno?” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “atos falhos: por que começar pelo pequeno?”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"As Conferências introdutórias foram construídas a partir de apresentações dirigidas a estudantes e leitores não especializados. Freud passa por atos falhos, sonhos e teoria das neuroses. O caráter pedagógico facilita a entrada na psicanálise, mas cada conferência traz teses que precisam ser relacionadas aos debates de seu momento."},{"title":"Entenda o conceito: Atos falhos: por que começar pelo pequeno?","body":"Freud parte de acontecimentos cotidianos para apresentar a hipótese de determinações psíquicas. Um exemplo persuasivo não vale como regra de interpretação de todos os erros.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Em 1933 Freud publicará Novas conferências introdutórias, o que permite comparar duas apresentações do mesmo campo teórico em momentos diferentes."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “atos falhos: por que começar pelo pequeno?”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Quem assiste a uma aula introdutória pode sair convencido de que entendeu a 'essência' de um sintoma. O desafio é retornar ao texto e separar explicações didáticas de trabalho singular com pacientes.\n\nAgora retome o foco desta aula: atos falhos: por que começar pelo pequeno?. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Conferências introdutórias","desc":"Aulas de Freud destinadas a apresentar sua teoria a um público de formação diversa."},{"term":"Sintoma","desc":"Formação clínica cuja concepção varia ao longo da teoria psicanalítica."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “atos falhos: por que começar pelo pequeno?” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1916–1917, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Atos falhos: por que começar pelo pequeno?” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1916–1917) — Conferências Introdutórias Sobre Psicanálise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a085","title":"Conferências Introdutórias Sobre Psicanálise #2","minutes":15,"hook":"Qual é o problema teórico por trás de “sonhos: associação e interpretação” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “sonhos: associação e interpretação”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"As Conferências introdutórias foram construídas a partir de apresentações dirigidas a estudantes e leitores não especializados. Freud passa por atos falhos, sonhos e teoria das neuroses. O caráter pedagógico facilita a entrada na psicanálise, mas cada conferência traz teses que precisam ser relacionadas aos debates de seu momento."},{"title":"Entenda o conceito: Sonhos: associação e interpretação","body":"A exposição retomada por Freud simplifica uma teoria elaborada desde 1900. Compare a fala didática com o trabalho detalhado do livro original.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Em 1933 Freud publicará Novas conferências introdutórias, o que permite comparar duas apresentações do mesmo campo teórico em momentos diferentes."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “sonhos: associação e interpretação”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Quem assiste a uma aula introdutória pode sair convencido de que entendeu a 'essência' de um sintoma. O desafio é retornar ao texto e separar explicações didáticas de trabalho singular com pacientes.\n\nAgora retome o foco desta aula: sonhos: associação e interpretação. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Conferências introdutórias","desc":"Aulas de Freud destinadas a apresentar sua teoria a um público de formação diversa."},{"term":"Sintoma","desc":"Formação clínica cuja concepção varia ao longo da teoria psicanalítica."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “sonhos: associação e interpretação” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1916–1917, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Sonhos: associação e interpretação” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1916–1917) — Conferências Introdutórias Sobre Psicanálise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a086","title":"Conferências Introdutórias Sobre Psicanálise #3","minutes":15,"hook":"Qual é o problema teórico por trás de “sintomas e conflito” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “sintomas e conflito”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"As Conferências introdutórias foram construídas a partir de apresentações dirigidas a estudantes e leitores não especializados. Freud passa por atos falhos, sonhos e teoria das neuroses. O caráter pedagógico facilita a entrada na psicanálise, mas cada conferência traz teses que precisam ser relacionadas aos debates de seu momento."},{"title":"Entenda o conceito: Sintomas e conflito","body":"A teoria das neuroses vincula sofrimento, defesa e satisfação substitutiva. Não reduza condições clínicas atuais a uma equação etiológica única.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Em 1933 Freud publicará Novas conferências introdutórias, o que permite comparar duas apresentações do mesmo campo teórico em momentos diferentes."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “sintomas e conflito”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Quem assiste a uma aula introdutória pode sair convencido de que entendeu a 'essência' de um sintoma. O desafio é retornar ao texto e separar explicações didáticas de trabalho singular com pacientes.\n\nAgora retome o foco desta aula: sintomas e conflito. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Conferências introdutórias","desc":"Aulas de Freud destinadas a apresentar sua teoria a um público de formação diversa."},{"term":"Sintoma","desc":"Formação clínica cuja concepção varia ao longo da teoria psicanalítica."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “sintomas e conflito” nesta obra?","options":["Examinar o argumento no contexto de 1916–1917, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Sintomas e conflito” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1916–1917) — Conferências Introdutórias Sobre Psicanálise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a087","title":"Conferências Introdutórias Sobre Psicanálise #4","minutes":15,"hook":"Qual é o problema teórico por trás de “transferência e possibilidades do método” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “transferência e possibilidades do método”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"As Conferências introdutórias foram construídas a partir de apresentações dirigidas a estudantes e leitores não especializados. Freud passa por atos falhos, sonhos e teoria das neuroses. O caráter pedagógico facilita a entrada na psicanálise, mas cada conferência traz teses que precisam ser relacionadas aos debates de seu momento."},{"title":"Entenda o conceito: Transferência e possibilidades do método","body":"Freud discute o tratamento no contexto da relação e das resistências. O estudante deve observar tanto promessas quanto condições e limites do que era possível afirmar na época.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Em 1933 Freud publicará Novas conferências introdutórias, o que permite comparar duas apresentações do mesmo campo teórico em momentos diferentes."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “transferência e possibilidades do método”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Quem assiste a uma aula introdutória pode sair convencido de que entendeu a 'essência' de um sintoma. O desafio é retornar ao texto e separar explicações didáticas de trabalho singular com pacientes.\n\nAgora retome o foco desta aula: transferência e possibilidades do método. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Conferências introdutórias","desc":"Aulas de Freud destinadas a apresentar sua teoria a um público de formação diversa."},{"term":"Sintoma","desc":"Formação clínica cuja concepção varia ao longo da teoria psicanalítica."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “transferência e possibilidades do método” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1916–1917, distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “Transferência e possibilidades do método” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1916–1917) — Conferências Introdutórias Sobre Psicanálise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a088","title":"Luto e Melancolia #1","minutes":18,"hook":"Qual é o problema teórico por trás de “o trabalho do luto” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “o trabalho do luto”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud contrapõe luto e melancolia para explorar perda, investimento e identificação. O texto foi escrito em 1915 e publicado em 1917. Seu uso contemporâneo exige não transformar uma distinção histórica em diagnóstico automático de depressão, nem patologizar reações normais diante de perdas."},{"title":"Entenda o conceito: O trabalho do luto","body":"Freud discute a relação entre perda e retirada gradual de investimentos. O curso do luto não é linear ou igual para todos; prazos fixos são simplificações indevidas.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto prepara discussões sobre identificação, supereu e segunda tópica. É preciso distinguir luto, depressão e a categoria histórica 'melancolia'."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “o trabalho do luto”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sofre intensamente pela morte de alguém querido. A dor, por si só, não indica patologia. A escuta precisa considerar vínculo, cultura, tempo e possibilidades de apoio, além das hipóteses teóricas.\n\nAgora retome o foco desta aula: o trabalho do luto. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Luto","desc":"Processo de resposta à perda, descrito por Freud em termos de investimento e trabalho psíquico."},{"term":"Melancolia","desc":"Categoria histórica e teórica usada por Freud para discutir perda e autorrecriminações."},{"term":"Identificação","desc":"Processo pelo qual aspectos de outro podem integrar a organização psíquica do eu."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “o trabalho do luto” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1917 [escrito em 1915], distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “O trabalho do luto” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1917 [escrito em 1915]) — Luto e Melancolia. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a089","title":"Luto e Melancolia #2","minutes":15,"hook":"Qual é o problema teórico por trás de “melancolia e autorrecriminação” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “melancolia e autorrecriminação”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud contrapõe luto e melancolia para explorar perda, investimento e identificação. O texto foi escrito em 1915 e publicado em 1917. Seu uso contemporâneo exige não transformar uma distinção histórica em diagnóstico automático de depressão, nem patologizar reações normais diante de perdas."},{"title":"Entenda o conceito: Melancolia e autorrecriminação","body":"O texto explora autoracusações intensas e suas possíveis ligações com relações de objeto. Tais hipóteses não substituem avaliação de sofrimento depressivo e risco clínico.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto prepara discussões sobre identificação, supereu e segunda tópica. É preciso distinguir luto, depressão e a categoria histórica 'melancolia'."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “melancolia e autorrecriminação”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sofre intensamente pela morte de alguém querido. A dor, por si só, não indica patologia. A escuta precisa considerar vínculo, cultura, tempo e possibilidades de apoio, além das hipóteses teóricas.\n\nAgora retome o foco desta aula: melancolia e autorrecriminação. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Luto","desc":"Processo de resposta à perda, descrito por Freud em termos de investimento e trabalho psíquico."},{"term":"Melancolia","desc":"Categoria histórica e teórica usada por Freud para discutir perda e autorrecriminações."},{"term":"Identificação","desc":"Processo pelo qual aspectos de outro podem integrar a organização psíquica do eu."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “melancolia e autorrecriminação” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1917 [escrito em 1915], distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Melancolia e autorrecriminação” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1917 [escrito em 1915]) — Luto e Melancolia. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a090","title":"Luto e Melancolia #3","minutes":15,"hook":"Qual é o problema teórico por trás de “identificação e ambivalência” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “identificação e ambivalência”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud contrapõe luto e melancolia para explorar perda, investimento e identificação. O texto foi escrito em 1915 e publicado em 1917. Seu uso contemporâneo exige não transformar uma distinção histórica em diagnóstico automático de depressão, nem patologizar reações normais diante de perdas."},{"title":"Entenda o conceito: Identificação e ambivalência","body":"A melancolia permite a Freud teorizar modos de identificação com o objeto perdido e conflitos de amor e hostilidade. Essa construção será importante para sua concepção posterior do eu.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto prepara discussões sobre identificação, supereu e segunda tópica. É preciso distinguir luto, depressão e a categoria histórica 'melancolia'."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “identificação e ambivalência”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sofre intensamente pela morte de alguém querido. A dor, por si só, não indica patologia. A escuta precisa considerar vínculo, cultura, tempo e possibilidades de apoio, além das hipóteses teóricas.\n\nAgora retome o foco desta aula: identificação e ambivalência. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Luto","desc":"Processo de resposta à perda, descrito por Freud em termos de investimento e trabalho psíquico."},{"term":"Melancolia","desc":"Categoria histórica e teórica usada por Freud para discutir perda e autorrecriminações."},{"term":"Identificação","desc":"Processo pelo qual aspectos de outro podem integrar a organização psíquica do eu."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “identificação e ambivalência” nesta obra?","options":["Examinar o argumento no contexto de 1917 [escrito em 1915], distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Identificação e ambivalência” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1917 [escrito em 1915]) — Luto e Melancolia. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]}]});
